const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('sv-SE').format(n), dayLabel=(d,opts={day:'numeric',month:'short'})=>new Intl.DateTimeFormat('sv-SE',opts).format(new Date(d+'T12:00:00'));
const nav=[['today','home','Idag'],['training','dumbbell','Träning'],['skills','tree','Skill tree'],['habits','list','Vanor'],['journey','compass','Expedition'],['squad','users','Social'],['profile','person','Profil']];
const dockTabs=['today','training','skills','squad'];
const langSwitch=()=>`<div class="lang-switch" role="group" aria-label="Språk">${Object.entries(languages).map(([k,n])=>button(n,'lang:'+k,`chip ${lang===k?'active':''}`,`aria-pressed="${lang===k}" lang="${k}" data-no-translate`)).join('')}</div>`;
// True when opened from the home screen (installed PWA); then install prompts are hidden.
const installed=()=>window.matchMedia?.('(display-mode: standalone)').matches===true||navigator.standalone===true;
startTranslating();
applyTheme();
const themePicker=()=>`<div class="theme-picker" role="group" aria-label="Färgtema">${Object.entries(themes).map(([k,t])=>`<button class="theme-choice ${theme===k?'active':''}" data-action="theme:${k}" aria-pressed="${theme===k}"><span class="theme-swatch" aria-hidden="true">${t.swatch.map(c=>`<i style="background:${c}"></i>`).join('')}</span><strong>${t.name}</strong><small>${t.hint}</small></button>`).join('')}</div>`;
const developmentModes=config.developmentModes===true;
const firstVisit=!localStorage.getItem('arc-mode');
const oauthFailure=new URL(location.href).searchParams.has('error');
const expiredOAuth=new URL(location.href).searchParams.get('error_code')==='bad_oauth_state';
let mode=localStorage.getItem('arc-mode')||'demo',state,route='today',tab='',filter='all',selectedDay=D.dateKey(),squad=null,social={posts:[],members:[],missions:[]},busy=false,syncStatus='',modalFocus=null;
let socialError='',socialRequest=0;
const actionLocks=new Set();
const draftKey=()=>`arc-post-draft-${selfId()}`;
function readPostDraft(){try{return JSON.parse(localStorage.getItem(draftKey()))||{};}catch{return {};}}
let demoSocial=null;
try{const cached=JSON.parse(localStorage.getItem('arc-demo-social')||'null');if(Array.isArray(cached))demoSocial=cached;}catch{}
const today=()=>D.dateKey(new Date(),state?.timezone);
const fitness=createFitnessUI({skillStartReady:()=>mode!=='cloud'||cloud.skillStartReady,getState:()=>state,D,I,character,esc,button:(...a)=>button(...a),bar:(...a)=>bar(...a),fmt,today,modal,form,commit,render,navTo,toast,closeModal});
const skillTree=createSkillTreeUI({I,esc,render:()=>render(),categories:{calisthenics:{view:()=>fitness.skillsView(),progress:()=>{const x=SK.summary(state);return {done:x.levels,total:x.total};}}}});
const friends=createFriendsUI({I,esc,button:(...a)=>button(...a),avatar:(...a)=>avatar(...a),character,D,F,getMode:()=>mode,cloud:{friends:cloud.friendsOverview,myFriendCode:cloud.myFriendCode,requestFriend:cloud.requestFriend,respondFriend:cloud.respondFriend,removeFriend:cloud.removeFriend},modal:(...a)=>modal(...a),closeModal:(...a)=>closeModal(...a),toast:(...a)=>toast(...a),render:()=>render()});
const strength=createStrengthUI({skillsEnabled:()=>mode!=='cloud'||cloud.skillWorkoutsReady,coreReady:()=>mode!=='cloud'||cloud.coreCatalogReady,skillsView:fitness.skillsView,skillThumb:fitness.skillThumb,openSkill:fitness.openSkill,showWorkout:()=>{fitness.action(['section','strength']);navTo('training');},enabled:()=>mode!=='cloud'||cloud.trainingReady,getState:()=>state,I,esc,button:(...a)=>button(...a),modal,form,commit,render,today,closeModal,toast});
const localKey=()=>`arc-state-${mode}`;
function readLocal(){try{return JSON.parse(localStorage.getItem(localKey()));}catch{return null;}}
function persistLocal(){localStorage.setItem(localKey(),JSON.stringify(state));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
const button=(text,action,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const bar=(n,color='')=>`<div class="bar"><span style="width:${Math.min(100,Math.max(0,n*100))}%;${color?'background:'+color:''}"></span></div>`;
const avatar=(name,cls='')=>name===state?.profile?.name&&state.profile.photo?`<span class="avatar ${cls}"><img data-photo="${esc(state.profile.photo)}" alt="Din profilbild"></span>`:`<span class="avatar ${cls}">${esc(name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span>`;
const empty=(icon,title,text,action,label)=>`<div class="empty">${I(icon)}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action?button(label,action):''}</div>`;
const notice=text=>`<div class="notice">${I('info')}<span>${text}</span></div>`;
// Character stats: XP-based stats plus skill-tree levels and completed personal goals.
function cstats(){return SK.characterStats(D.stats(state),state,D.categories);}
function tier(){const l=D.levelInfo(D.totalXP(state)).level;return ['Vandrare','Frostvandrare','Norrskensväktare','Vinterlegend'][Math.min(3,Math.floor((l-1)/5))];}
function demoMembers(){return [{user_id:'maya',display_name:'Maya',xp:6370,streak:18,perfect_today:true,completed_week:29,training_streak:11,trained_today:true},{user_id:'noah',display_name:'Noah',xp:5810,streak:14,perfect_today:true,completed_week:26,training_streak:6,trained_today:false},{user_id:'me',display_name:state.profile.name,xp:D.totalXP(state),streak:D.streak(state,today()),perfect_today:D.progress(state,today()).perfect,...myTraining(),completed_week:Object.entries(state.history).filter(([d])=>d>=D.weekKey(today())&&d<=today()).reduce((n,[d])=>n+D.progress(state,d).done,0)},{user_id:'elliot',display_name:'Elliot',xp:4260,streak:9,perfect_today:false,completed_week:21,training_streak:0,trained_today:false}].sort((a,b)=>b.xp-a.xp);}
function members(){if(mode==='demo')return demoMembers();return social.members.map(m=>m.user_id===cloud.user?.id?{...m,display_name:state.profile.name,xp:D.totalXP(state),streak:D.streak(state,today()),perfect_today:D.progress(state,today()).perfect,...(m.training_streak==null?{}:myTraining())}:m);}
function myTraining(){const st=streakStatus(state,today());return {training_streak:st.days,trained_today:st.trainedToday};}
function trainingBoard(){const ms=members(),ready=ms.some(m=>m.training_streak!=null);return `<section class="card training-board"><div class="section-head"><h2>Träningsstreaks</h2>${I('flame')}</div><p class="muted">En flamma per dag med ett sparat pass i Styrkehubben. En vilodag i taget är okej, två i rad släcker flamman.</p>${ready?ms.filter(m=>m.training_streak!=null).sort((a,b)=>b.training_streak-a.training_streak||Number(b.trained_today)-Number(a.trained_today)).map(m=>`<div class="streak-row ${m.user_id===selfId()?'me':''}">${avatar(m.display_name)}<span class="leader-name"><strong>${esc(m.display_name)}${m.user_id===selfId()?' <span class="muted">(du)</span>':''}</strong><small>${m.trained_today?'Har tränat idag':m.training_streak?'Vilar eller tränar senare':'Ingen aktiv streak'}</small></span><span class="flame-badge ${m.trained_today?'lit':''} ${m.training_streak?'':'out'}" aria-label="${m.training_streak} träningsdagar">${I('flame')}${m.training_streak}</span></div>`).join(''):`<p class="fitness-hint">Träningsstreaks visas här när databasuppdateringen 011 är installerad.</p>`}</section>`;}
const selfId=()=>mode==='demo'?'me':cloud.user?.id;
function demoPosts(){if(!demoSocial){demoSocial=[{id:'demo1',user_id:'maya',name:'Maya',body:'Lite tröttare idag, men jag dök upp. 30 min löpning och frisk luft. Det räknas. 🌲',created_at:new Date(Date.now()-1000*60*45).toISOString(),badge:'18 dagar. Samma löfte.',reactions:[{user_id:'noah',kind:'fire'},{user_id:'elliot',kind:'heart'}]},{id:'demo2',user_id:'noah',name:'Noah',body:'Läste klart Atomic Habits igår. Min största lärdom: gör det så litet att det är svårt att säga nej. Idag blev det tio sidor igen.',created_at:new Date(Date.now()-1000*60*120).toISOString(),badge:'Wisdom +25 XP',reactions:[{user_id:'maya',kind:'clap'}]}];}return demoSocial;}
function navTo(r,t=''){route=r;tab=t;const defaultTabs=currentTabs();if(!tab&&defaultTabs.length)tab=defaultTabs[0][0];filter='all';closeModal(false);location.hash=r+(tab?'/'+tab:'');render();window.scrollTo({top:0,behavior:'instant'});if(r==='squad'&&mode==='cloud')refreshSocial();}
function currentTabs(){return route==='habits'?[['mine','Mina vanor'],['library','Utforska'],['goals','Mål']]:route==='journey'?[['overview','Översikt'],['skills','Skill tree'],['badges','Achievements'],['rewards','Belöningar']]:route==='squad'?[['friends','Vänner'],['feed','Squad'],['leaderboard','Leaderboard'],['missions','Uppdrag']]:route==='profile'?[['character','Karaktär'],['body','Kroppstracker'],['journal','Bildjournal'],['reflections','Reflektion'],['wrapped','Wrapped'],['private','Privata mål']]:[];}
function tabsHTML(){const tabs=currentTabs();if(!tab&&tabs.length)tab=tabs[0][0];return tabs.length?`<div class="tabs" role="tablist">${tabs.map(([k,n])=>`<button class="tab ${tab===k?'active':''}" role="tab" aria-selected="${tab===k}" data-action="tab:${k}">${n}</button>`).join('')}</div>`:'';}
let displayedDate='',displayedView='';
function render(){
 if(!developmentModes&&mode!=='cloud'){$('#app').innerHTML=`<main class="release-welcome"><div class="brand-mark"><img src="./icon-192.png" alt=""></div><span class="eyebrow">BEYOND SELF · DIN EXPEDITION</span><h1>Din nästa nivå.<br>Tillsammans.</h1><p>Bygg dina vanor. Utveckla din karaktär.<br>Ta med ditt squad hela vägen.</p><div class="welcome-art">${landscape()}</div>${button('<span class="google-logo">G</span> Fortsätt med Google','google','btn full',!cloud.googleReady?'disabled':'')}<small>Ett eget konto. Framsteg som sparas i molnet.</small>${installed()?'':button('Lägg till på hemskärmen','install','btn ghost full')}${button('Försök hämta kontot igen','reload','btn ghost full')}${langSwitch()}</main>`;return;}

 const defaultTabs=currentTabs();if(!tab&&defaultTabs.length)tab=defaultTabs[0][0];
 if(displayedDate!==today()){applyPending();selectedDay=today();displayedDate=today();}
 const prevRoute=displayedView.split('/')[0],routeChanged=prevRoute!==route;const animateView=displayedView!==route+'/'+tab;displayedView=route+'/'+tab;const xp=D.totalXP(state),level=D.levelInfo(xp),p=D.progress(state,today());const title={today:'Ett steg framåt.',training:'Bygg din nästa nivå.',skills:'Lås upp nästa skill.',habits:'Små steg. Stor förändring.',journey:'Bli den du vill vara.',squad:'Starkare tillsammans.',profile:'Din berättelse, hittills.'}[route];
 const subtitle={training:'Styrka, rörlighet och ett lugnare fokus. I din takt.',skills:'Välj ett skill tree och ta nästa steg. Nivåerna låses upp av dina sparade pass.',today:`Välkommen tillbaka, ${state.profile.name}. Varje litet steg räknas.`,habits:'Bygg system som gör det lätt att dyka upp.',journey:'En karaktär att utveckla. En expedition att slutföra.',squad:'Dela resan. Fira framstegen. Håll varandra ansvariga.',profile:'Se hur långt du har kommit. Och vart du är på väg.'}[route];
 const mark=`<span class="brand-mark"><img src="./icon-192.png" alt=""></span><span class="brand">BEYOND SELF<small>THE EXPEDITION</small></span>`;
 $('#app').innerHTML=`<aside class="sidebar"><div class="flex">${mark}</div><nav aria-label="Huvudmeny">${nav.map(([k,i,n])=>`<button class="nav-btn ${route===k?'active':''}" data-action="nav:${k}" ${route===k?'aria-current="page"':''}>${I(i)}${n}</button>`).join('')}</nav><div class="season-note">${I('mountain')}<div class="eyebrow">Din Winter Arc</div><h3>90 dagar. En ny nivå.</h3><p>Du behöver inte vara perfekt.<br>Du behöver bara börja.</p></div><div class="sidebar-bottom">${installed()?'':button(I('info')+' Installera på iPhone','install','btn ghost')}<button class="profile-menu" data-action="nav:profile">${avatar(state.profile.name)}<span><strong style="font-size:12px">${esc(state.profile.name)}</strong><small class="muted" style="display:block;font-size:10px;margin-top:4px">Level ${level.level} · ${tier()}</small></span>${I('chevron')}</button></div></aside><main class="shell"><header class="topbar"><div class="breadcrumb">Beyond Self <span class="slash">/</span> ${nav.find(x=>x[0]===route)[2]}</div><div class="mobile-brand flex">${mark}</div><div class="top-actions"><button class="pill ${mode==='demo'?'demo':''}" data-action="${mode==='cloud'?'sync':'auth'}">${I(mode==='cloud'?'check':'info')}${mode==='demo'?'Demoläge':mode==='cloud'?(syncStatus||'Molnsynkat'):'På den här enheten'}</button>${button(I('bell'),'notifications','icon-btn','aria-label="Notiser"')}${button(I('settings'),'settings','icon-btn top-settings','aria-label="Inställningar"')}${button(avatar(state.profile.name),'nav:profile','profile-menu top-avatar','aria-label="Öppna din profil"')}</div></header><div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="page-actions">${route==='today'?`<span class="date">${I('calendar')} <span>${dayLabel(today(),{weekday:'long',day:'numeric',month:'long'})}</span></span>`:route==='habits'?button(I('plus')+' Ny vana','new-habit'):route==='squad'?(tab==='friends'?button(I('plus')+' Lägg till vän','friend:add'):button(I('plus')+' Bjud in','invite')):''}</div></div>${tabsHTML()}<div id="view" class="${animateView?'view-enter':''}">${route==='today'?todayView():route==='training'?fitness.trainingView(strength.view()):route==='skills'?skillTree.view():route==='habits'?habitsView():route==='journey'?journeyView():route==='squad'?squadView():profileView()}</div></main><div class="dock"><nav class="tabbar ${routeChanged&&dockTabs.includes(prevRoute)?'nav-arrived':''}" aria-label="Mobilmeny" style="--i:${dockTabs.indexOf(route)};--from:${dockTabs.indexOf(prevRoute)}">${dockTabs.map(k=>nav.find(x=>x[0]===k)).map(([k,i,n])=>`<button class="${route===k?'active':''}" data-action="nav:${k}" ${route===k?'aria-current="page"':''}>${I(i)}<span>${n}</span></button>`).join('')}</nav>${button(I('plus'),'quick','dock-plus','aria-label="Snabbval" aria-haspopup="dialog"')}</div>`;
 hydrateImages();
}
function hero(journey=false){const day=D.expeditionProgress(state,today());return `<div class="hero ${journey?'journey':''}">${landscape()}<div><span class="eyebrow">${I('snow')} WINTER ARC · DIN 90-DAGARSRESA</span><h2>${journey?'Det här är<br>din förvandling.':'Din nästa nivå<br>börjar idag.'}</h2><p>${journey?'Du bygger mer än vanor. Du bygger tillit till dig själv. En dag i taget.':'Små handlingar. Varje dag.<br>En starkare version av dig.'}</p></div><div class="hero-bottom"><div class="hero-progress"><div class="flex between"><small style="font-size:10px">Dag ${day} <span style="opacity:.55">av ${state.expedition.days}</span></small><small style="font-size:10px;color:#c6d7c8">${Math.round(day/state.expedition.days*100)}%</small></div>${bar(day/state.expedition.days)}</div>${button(I('arrow'),'nav:journey','round-arrow','aria-label="Se din expedition"')}</div></div>`;}
function characterCard(){const xp=D.totalXP(state),l=D.levelInfo(xp),s=cstats(),max=Math.max(500,...Object.values(s));return `<section class="card character-card"><div class="section-head"><span class="eyebrow">Din karaktär</span><span class="level-badge">LVL ${l.level}</span></div>${character(l.level,false,state.profile.character)}<h3>${tier()}</h3><p>EVOLUTION ${Math.min(4,Math.floor((l.level-1)/5)+1)} · ${l.level<16?'NÄSTA FORM VID LEVEL '+(Math.floor((l.level-1)/5)*5+6):'SISTA FORMEN UPPLÅST'}</p><div class="xp-track"><b>${fmt(xp-l.base)} / ${fmt(l.next-l.base)} XP</b><span>Level ${l.level+1}</span></div>${bar(l.ratio)}<div class="stats-bars">${Object.entries(s).map(([name,v],i)=>`<div class="stat-line"><span>${name}</span>${bar(v/max,['#a7bcfa','#88d3cf','#ffca84','#c4b3ec','#ead398','#f3acc4','#e1b6d8'][i])}<b>${fmt(v)}</b></div>`).join('')}</div>${button('Se din karaktär '+I('arrow'),'nav:profile','btn ghost full')}</section>`;}
function squadMini(){const ms=members(),count=ms.filter(m=>m.perfect_today).length;return `<section class="card squad-card"><div class="section-head"><h3>Ditt squad</h3>${I('users')}</div>${ms.length?`<div class="flex between"><div class="faces">${ms.slice(0,5).map((m,i)=>avatar(m.display_name,['','gold','purple','blue'][i%4])).join('')}</div><span class="pill">${I('flame')}${ms.length?Math.min(...ms.map(m=>m.streak||0)):0} dagar</span></div><div class="space"><div class="squad-mini-title">${mode==='demo'?'The Northbound':esc(squad?.name||'Ditt squad')}</div><p>Alla framåt. Ingen lämnas kvar.</p></div>${bar(count/ms.length,'var(--gold)')}<div class="flex between progress-label"><span>${count} av ${ms.length} klara idag</span><span>${Math.round(count/ms.length*100)}%</span></div>${button('Till squadet '+I('arrow'),'nav:squad','btn ghost full')}`:`<p>Din expedition blir bättre tillsammans. Skapa ett squad och bjud in dina vänner.</p>${button('Hitta ditt squad '+I('arrow'),'invite','btn ghost full')}`}</section>`;}
function weekRow(){const monday=D.weekKey(today());return `<div class="week-row date-nav">${Array.from({length:7},(_,i)=>{const d=D.shiftDate(monday,i),p=D.progress(state,d);return `<button class="day ${p.perfect?'complete':''} ${d===selectedDay?'selected':''}" data-action="day:${d}" aria-label="${dayLabel(d,{weekday:'long',day:'numeric',month:'long'})}${p.perfect?', alla mål klara':''}" aria-pressed="${d===selectedDay}"><span>${['MÅN','TIS','ONS','TOR','FRE','LÖR','SÖN'][i]}</span><strong>${Number(d.slice(-2))}</strong><span class="dot"></span></button>`;}).join('')}</div>`;}
function habitRows(day=today(),withArchive=false){if(day<state.expedition.start&&day===today()&&!withArchive)return `<div class="card prestart-habits"><h3>Dina första steg är redo.</h3><p class="fitness-hint">${state.habits.filter(h=>!h.archived).length} planerade vanor · start ${state.expedition.start}. Inga missade dagar före start.</p>${button('Se och välj mina vanor','nav:habits','btn secondary full')}</div>`;const record=state.history[day],ids=record?.required,hs=day===today()?state.habits.filter(h=>withArchive?!h.archived:D.due(h,day)):(ids||[]).map(id=>state.habits.find(h=>h.id===id)||{id,...record.entries[id]}).filter(Boolean);if(!hs.length)return empty('list',day===today()?'En liten vana är en stor början.':'Inga vanor den här dagen.',day===today()?'Välj ett litet steg du vill ta idag.':'Välj idag för att fortsätta expeditionen.',day===today()?'new-habit':null,'Lägg till din första vana');return `<div class="habit-list">${hs.filter(h=>filter==='all'||h.category===filter).map(h=>{const e=record?.entries[h.id],done=e?.value>=e?.target,c=D.categories[h.category]||D.categories.discipline;return `<div class="habit-row ${done?'done':''}" style="--cat:${c.color}"><span class="habit-icon">${I(c.icon)}</span><div class="habit-info"><strong>${esc(h.name)}</strong><p><span>${fmt(e?.value||0)} / ${fmt(e?.target||h.target||1)} ${esc(h.unit||'')}${h.durationMinutes?' · '+h.durationMinutes+' min':''}</span><span>·</span><span class="mini-tag">${c.name}</span></p></div><span class="xp">+${h.durationMinutes?2*h.durationMinutes:h.xp||e?.xp||20} XP</span>${day===today()?withArchive?button(I('edit'),'edit-habit:'+h.id,'icon-btn','aria-label="Redigera '+esc(h.name)+'"'):button(I('check'),'habit:'+h.id,'check-btn',`aria-label="${done?'Ångra':'Registrera'} ${esc(h.name)}" aria-pressed="${!!done}"`):`<span class="check-btn" style="${done?'background:var(--mint);color:#1c3930':''}">${I(done?'check':'clock')}</span>`}</div>`;}).join('')}</div>`;}
function questRows(){if(today()<state.expedition.start)return notice('Dina dagliga uppdrag öppnas på startdagen. Utforska träning och välj dina vanor så länge.');return `<div class="quest-list">${D.quests(state,today()).map(q=>{const claimed=state.claims[q.id],ready=q.current>=q.target;return `<div class="quest-row ${claimed?'claimed':''}">${I(q.icon)}<div class="body"><h3>${q.name}</h3><p>${q.description}</p>${bar(q.current/q.target)}</div><div class="text-right"><span class="xp">+${q.xp} XP</span><br>${button(claimed?I('check'):ready?'Hämta':`${q.current}/${q.target}`,'claim:'+q.id,'btn ghost',claimed||!ready?'disabled':'')}</div></div>`;}).join('')}</div>`;}
function todaySummary(){const xp=D.totalXP(state),l=D.levelInfo(xp),rank=F.rankInfo(xp),c=F.characters.find(c=>c.id===state.profile.character)||F.characters[0];return `<section class="today-summary"><div><span class="eyebrow">${esc(state.profile.characterName||c.name)} · ${rank.name}</span><h2>Level ${l.level}<span>${fmt(l.next-xp)} XP till nästa</span></h2>${bar(l.ratio)}<p>Dag ${D.expeditionProgress(state,today())} av 90 · din egen expedition</p></div><button class="summary-character" data-action="nav:profile" aria-label="Öppna din karaktär">${character(l.level,false,c.id)}</button></section>`;}
function todayView(){const p=D.progress(state,today()),count=Object.values(state.history[today()]?.entries||{}).filter(e=>e.source!=='challenge'&&e.value>=e.target).length;return `<div class="dashboard"><div class="main-col">${fitness.season()}${todaySummary()}<div class="quick-links">${button(I('list')+' Mina vanor','nav:habits','quick-link')}${button(I('compass')+' Expedition','nav:journey','quick-link')}${button(I('person')+' Karaktär','nav:profile','quick-link')}</div>${streakCard({I,button},state,today())}<div class="mini-stats"><div class="mini-stat">${I('flame')}<strong>${D.streak(state,today())}<small style="font-size:11px;color:var(--muted);letter-spacing:0"> dagar</small></strong><span>Din vanestreak</span></div><div class="mini-stat">${I('check')}<strong>${p.done}<small style="font-size:14px;color:var(--muted)"> / ${p.total}</small></strong><span>Dagens vanor klara</span></div><div class="mini-stat">${I('gem')}<strong>${fmt(today()<state.expedition.start?0:D.dayXP(state.history[today()])+F.trainingXP(state,today())+S.strengthXP(state,today())+cardioXP(state,today()))}</strong><span>XP intjänade idag</span></div></div><section><div class="section-head"><h2>Dina dagliga steg <span class="count">${Math.round(D.progress(state,selectedDay).ratio*100)}%</span></h2>${button(I('plus')+' Lägg till','new-habit','btn ghost')}</div>${weekRow()}${habitRows(selectedDay)}${selectedDay===today()&&today()>=state.expedition.start&&!Object.values(state.history[today()]?.entries||{}).some(e=>e.durationMinutes)?`<div class="combo space"><div class="flex">${I('bolt')}<strong>${count>=3?'Combo aktiv':'Bygg din combo'}</strong><em>${count>=5?'Fem vanor. Fullt fokus.':'Tre vanor låser upp 1,2× XP'}</em></div><div class="tiny-dots">${Array.from({length:5},(_,i)=>`<i class="${count>i?'on':''}"></i>`).join('')}</div><strong>${D.multiplier(count).toLocaleString('sv-SE')}× XP</strong></div>`:''}</section><section><div class="section-head"><h2>Dagens uppdrag</h2><span class="eyebrow">Gör plats för framsteg</span></div>${questRows()}</section></div><aside class="side-col">${characterCard()}${squadMini()}<div class="quote">”Du stiger inte till nivån av dina mål.<br>Du faller till nivån av dina system.”<span>JAMES CLEAR · ATOMIC HABITS</span></div></aside></div>`;}
function categoryChips(){return `<div class="chips">${button('Alla','filter:all',`chip ${filter==='all'?'active':''}`)}${Object.entries(D.categories).map(([k,c])=>button(I(c.icon)+c.name,'filter:'+k,`chip ${filter===k?'active':''}`)).join('')}</div>`;}
function habitsView(){if(tab==='goals')return `<div class="section-head"><h2>Dina personliga mål</h2>${button(I('plus')+' Nytt mål','new-goal','btn ghost')}</div>${state.goals.length?`<div class="goals-grid">${state.goals.map(g=>`<section class="card goal-card"><span class="habit-icon" style="--cat:${D.categories[g.category].color}">${I(D.categories[g.category].icon)}</span><h3>${esc(g.name)}</h3><p>${g.current>=g.target?'Målet är nått. Du gjorde det.':`Måldatum ${dayLabel(g.deadline,{day:'numeric',month:'long',year:'numeric'})}`}</p>${bar(g.current/g.target)}<div class="flex between"><span class="muted" style="font-size:11px">${fmt(g.current)} / ${fmt(g.target)} ${esc(g.unit)}</span>${button('Uppdatera','goal:'+g.id,'btn secondary')}</div></section>`).join('')}</div>`:empty('flag','Vad vill du uppnå?','Sätt ett mål och följ din utveckling under expeditionen.','new-goal','Skapa ett mål')}`;
 if(tab==='library')return `${categoryChips()}<input class="search" type="search" id="library-search" placeholder="Sök bland vanor…" aria-label="Sök bland vanor"><div class="library-grid" id="library-results">${libraryCards()}</div>`;
 return `<div class="grid2 mobile-stack"><section class="card"><div class="section-head"><h2>Ditt system</h2><span class="pill">${state.habits.filter(h=>!h.archived).length} vanor</span></div><p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:20px">Gör det uppenbart. Gör det enkelt. Koppla varje vana till något du redan gör.</p>${categoryChips()}${habitRows(today(),true)}${button(I('plus')+' Skapa egen vana','new-habit','btn secondary full space')}</section><section class="card"><span class="eyebrow">Atomic habits · din metod</span><h2 style="margin:14px 0 10px">Bli 1% bättre.</h2><p class="muted" style="font-size:12px;line-height:1.9">Börja med en identitet. Vilken person vill du bli? Varje genomförd vana är en röst för den personen.</p>${[['01','Gör det uppenbart','Efter [befintlig vana] gör jag [ny vana].'],['02','Gör det attraktivt','Koppla ett litet steg till något du tycker om.'],['03','Gör det enkelt','Börja med två minuter. Sänk tröskeln.'],['04','Gör det tillfredsställande','Bocka av. Samla XP. Fira med ditt squad.']].map(([n,t,p])=>`<div class="settings-row"><span class="eyebrow">${n}</span><div style="flex:1"><h3>${t}</h3><p>${p}</p></div></div>`).join('')}${button('Utforska vanebiblioteket '+I('arrow'),'tab:library','btn ghost space')}</section></div>`;}
function libraryCards(query=''){const rows=D.library.map((item,i)=>({item,i})).filter(({item})=>(filter==='all'||item[1]===filter)&&item[0].toLocaleLowerCase('sv').includes(query.toLocaleLowerCase('sv')));return rows.length?rows.map(({item,i})=>{const c=D.categories[item[1]],exists=state.habits.some(h=>!h.archived&&h.name===item[0]);return `<section class="card library-card"><span class="habit-icon" style="--cat:${c.color}">${I(c.icon)}</span><h3>${item[0]}</h3><span class="xp">${item[2]} ${item[3]} · +${item[4]} XP</span><p>${item[5]}</p>${button(I(exists?'check':'plus')+(exists?'Tillagd':'Lägg till'),'library:'+i,'btn secondary',exists?'disabled':'')}</section>`;}).join(''):empty('list','Inga träffar','Prova ett annat sökord eller skapa en egen vana.','new-habit','Skapa egen vana');}
function journeyView(){if(tab==='skills'){const stats=cstats(),sum=SK.summary(state);return `<section class="card sk-link"><div><span class="eyebrow">CALISTHENICS · SKILL TREE</span><h3>${sum.levels} av ${sum.total} nivåer klara</h3><p class="muted">Från handstand till human flag. Varje nivå du klarar stärker din karaktär.</p></div>${button('Öppna skill tree '+I('arrow'),'fit:open-skills','btn secondary')}</section><p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:22px">Dina vanor, utmaningar, pass, skill-nivåer och uppnådda mål utvecklar sju livsområden. Varje milstolpe låser upp en ny nivå och en symbolisk förmåga.</p><div class="skill-grid">${Object.entries(stats).map(([name,value],i)=>{const c=Object.values(D.categories).find(c=>c.stat===name),titles=[['Grundstyrka','Uthållig','Orubblig'],['Rörelsefrihet','Kontroll','Smidighet'],['Fokus','Självledarskap','Järnvilja'],['Nyfiken','Insiktsfull','Mentor'],['Närvaro','Förankrad','Inre lugn'],['Kontakt','Gemenskap','Inspiratör'],['Lyssnare','Musiker','Musikalisk röst']][i];return `<section class="card skill-column" style="--cat:${c.color}"><h3>${name}</h3><p>${fmt(value)} stat-poäng</p>${[100,500,1500].map((threshold,j)=>`<div class="skill-node ${value>=threshold?'unlocked':''}">${I(value>=threshold?c.icon:'lock')}${titles[j]}<small>${fmt(threshold)} poäng ${value>=threshold?'· upplåst':''}</small></div>`).join('')}</section>`;}).join('')}</div>`;}
 if(tab==='badges')return `<div class="badge-grid">${D.achievements(state,today()).map(a=>`<section class="card badge-card ${a.unlocked?'':'locked'}"><div class="gem">${I(a.unlocked?a.icon:'lock')}</div><h3>${a.name}</h3><p>${a.description}</p>${bar(a.progress)}<p style="margin-top:10px;color:${a.unlocked?'var(--mint)':'var(--muted)'}">${a.unlocked?'Upplåst':Math.round(a.progress*100)+'% avklarat'}</p></section>`).join('')}</div>`;
 if(tab==='rewards'){const l=D.levelInfo(D.totalXP(state)).level;return `<p class="muted" style="font-size:12px;margin-bottom:23px;line-height:1.7">Framsteg förtjänar att firas. Lås upp visuella titlar och välj en belöning till dig själv.</p><div class="library-grid">${[[3,'En stund för dig','Planera en skärmfri favoritkväll.','En välförtjänt paus'],[6,'Frostvandrare','Din andra evolution och en ny profiltitel.','Frostvandrare'],[11,'Norrskensväktare','En ny form. En ny nivå av tillit.','Norrskensväktare'],[16,'Vinterlegend','Du har gjort utveckling till din identitet.','Vinterlegend']].map(([n,title,desc,reward])=>`<section class="card reward-card"><div class="gem">${I(l>=n?'gift':'lock')}</div><h3>${title}</h3><p>${desc}<br>Level ${n}</p>${button(state.rewards.includes(n)?'Hämtad':l>=n?'Hämta belöning':'Låst','reward:'+n,'btn secondary full',l<n||state.rewards.includes(n)?'disabled':'')}</section>`).join('')}</div>`;}
 const day=D.expeditionProgress(state,today());return `<div class="dashboard"><div class="main-col">${hero(true)}<section class="card"><h2>Din väg genom vintern</h2><div class="map-stages">${[[1,'Början'],[15,'Momentum'],[30,'Förankring'],[60,'Förvandling'],[90,'Din nya nivå']].map(([d,n])=>`<div class="stage ${day>=d?'done':''} ${day>=d&&day<d+15?'current':''}"><span>${I(day>=d?'check':'lock')}</span><small>DAG ${d}</small><strong>${n}</strong></div>`).join('')}</div>${notice('Din streak nollställs efter en missad dag. Din XP och din utveckling finns alltid kvar. En comeback-quest hjälper dig tillbaka.')}</section><section><div class="section-head"><h2>Dina uppdrag</h2><span class="eyebrow">En liten seger i taget</span></div>${questRows()}</section><section class="card"><div class="section-head"><h2>Veckans reflektion</h2>${I('book')}</div><p class="muted" style="font-size:12px;line-height:1.8">Vad fungerade? Vad var svårt? Vilket litet steg gör nästa vecka bättre?</p>${button('Ta en stund för reflektion '+I('arrow'),'reflection','btn secondary space')}</section></div><aside class="side-col">${characterCard()}${squadMini()}</aside></div>`;}
function squadView(){if(tab==='friends')return friends.view();if(socialError)return `${notice(esc(socialError))}${button('Försök hämta squadet igen','refresh-social','btn secondary space')}${social.posts.length?'':empty('users','Tillfälligt avbrott','Du är fortfarande inloggad. Försök igen när anslutningen fungerar.')}${social.posts.length?feedView():''}`;return feedView();}
function feedView(){if(mode!=='demo'&&!squad)return `${notice(mode==='cloud'?'Skapa ett privat squad eller gå med via en inbjudningskod.':'Vänners data synkas när Supabase och Google-inloggning har anslutits. I demoläget kan du prova hela upplevelsen.')}<div class="space">${empty('users','Din resa behöver inte vara ensam.','Bjud in dina vänner. Bygg en gemensam streak, klara uppdrag och fira de små segrarna.','invite',mode==='cloud'?'Skapa eller gå med i squad':'Anslut ditt konto')}</div>`;
 if(tab==='leaderboard'){return `<div class="grid2 mobile-stack"><section class="card"><div class="section-head"><h2>Expeditionens leaderboard</h2>${I('trophy')}</div><p class="muted" style="font-size:11px;line-height:1.8;margin-bottom:12px">${mode==='demo'?'The Northbound · exempeldata':esc(squad?.name)} · totalt intjänade XP</p>${members().sort((a,b)=>b.xp-a.xp).map((m,i)=>`<div class="leader-row ${m.user_id===selfId()?'me':''}"><span class="rank">${i===0?I('trophy'):i+1}</span>${avatar(m.display_name,['','gold','purple','blue'][i%4])}<span class="leader-name"><strong>${esc(m.display_name)} ${m.user_id===selfId()?'<span class="muted">(du)</span>':''}</strong><small>${F.rankInfo(m.xp).name} · LVL ${D.levelInfo(m.xp).level} · ${m.streak||0} dagars vanestreak</small></span>${m.training_streak!=null?`<span class="flame-badge ${m.trained_today?'lit':''} ${m.training_streak?'':'out'}" title="Träningsstreak" aria-label="Träningsstreak ${m.training_streak} dagar">${I('flame')}${m.training_streak}</span>`:''}<span class="xp">${fmt(m.xp)} XP</span></div>`).join('')}</section><div class="stack">${trainingBoard()}${squadMini()}${notice('Ni tävlar i att dyka upp, inte i att vara perfekta. Varje vana är självrapporterad. Uppmuntra varandra och håll det ärligt.')}</div></div>`;}
 if(tab==='missions'){const ms=members(),completed=ms.reduce((sum,m)=>sum+(m.completed_week||0),0),missions=mode==='demo'?[{id:'demo-mission',name:'100 små segrar',target:100,deadline:D.shiftDate(D.weekKey(today()),6),created_at:D.weekKey(today())}]:social.missions;return `<div class="section-head"><h2>Squad missions</h2>${button(I('plus')+' Nytt uppdrag','new-mission','btn ghost')}</div>${missions.length?`<div class="goals-grid">${missions.map(m=>{const current=mode==='demo'?completed:(m.completed||0);return `<section class="card mission-card"><span class="pill demo">${I('flag')} VECKOUPPDRAG</span><div class="flex"><div class="habit-icon" style="--cat:var(--gold)">${I('mountain')}</div><h3>${esc(m.name)}</h3></div><p>Genomför vanor tillsammans den här veckan. Varje steg i squadet räknas.</p>${bar(current/m.target)}<div class="flex between"><span class="xp">${fmt(current)} / ${fmt(m.target)} vanor</span><span class="muted" style="font-size:10px">Till ${dayLabel(m.deadline)}</span></div><div class="space"><span class="pill">${current>=m.target?I('check')+' Uppdrag slutfört':I('users')+' '+ms.length+' deltagare'}</span></div></section>`;}).join('')}</div>`:empty('flag','Ert nästa gemensamma mål','Starta ett veckouppdrag. Alla i squadet bidrar med sina genomförda vanor.','new-mission','Skapa squad mission')}`;}
 const posts=mode==='demo'?demoPosts():social.posts;return `<div class="dashboard"><div class="main-col"><div class="feed" style="width:100%">${mode==='cloud'&&!social.activityReady?notice('Automatisk aktivitetsdelning och bilder på befintliga inlägg inväntar databasuppdateringen. Vanliga inlägg och reaktioner fungerar.'):''}${mode==='demo'?notice('Du utforskar ett demosquad. Maya, Noah och Elliot är exempelprofiler. Inlägg och reaktioner här sparas bara på den här enheten.'):''}<button class="card post-composer ${mode==='demo'?'space':''}" data-action="new-post">${avatar(state.profile.name)}<span>Dela ett steg i din expedition…</span>${I('camera')}</button>${posts.length?posts.map(p=>{const name=p.name||p.profiles?.display_name||'Äventyrare',reaction=p.reactions||[];return `<article class="card post"><div class="post-head">${avatar(name,p.user_id==='maya'?'gold':p.user_id==='noah'?'blue':'')}<div><strong>${esc(name)}${p.user_id===selfId()?' <span class="muted">· du</span>':''}</strong><small>${new Date(p.created_at).toLocaleDateString('sv-SE',{day:'numeric',month:'short'})} · ${mode==='demo'?'Demosquad':esc(squad?.name||'Ditt squad')}</small></div>${p.user_id===selfId()?button(I('edit'),'delete-post:'+p.id,'icon-btn','aria-label="Hantera ditt inlägg" style="margin-left:auto"'):''}</div><p class="post-text">${esc(p.body)}</p>${p.user_id===selfId()?button(I('camera')+(p.image_path?' Byt bild':' Lägg till bild'),'post-photo:'+p.id,'btn ghost',mode==='cloud'&&!social.activityReady?'disabled':''):''}${p.image_path?`<div class="post-media"><img class="post-image" data-photo="${esc(p.image_path)}" alt="Accountability-bild delad i squadet" loading="lazy"><div class="photo-fallback" hidden>${I('camera')}<p>Bilden kunde inte hämtas.</p><small>Prova igen. Om filen saknas behöver den laddas upp på nytt.</small>${button('Försök igen','retry-photo:'+p.id,'btn ghost')}</div></div>`:''}${p.badge?`<div class="post-achievement">${I('flame')}<div><strong>${esc(p.badge)}</strong><small>Små segrar blir stora förändringar.</small></div></div>`:''}<div class="reactions">${[['fire','🔥'],['clap','👏'],['heart','💚']].map(([k,emoji])=>{const active=reaction.some(r=>r.user_id===selfId()&&r.kind===k);return button(`${emoji} <span>${reaction.filter(r=>r.kind===k).length}</span>`,'react:'+p.id+':'+k,`react-btn ${active?'active':''}`,`aria-label="Reagera med ${k==='fire'?'eld':k==='clap'?'applåder':'hjärta'}" aria-pressed="${active}"`);}).join('')}</div></article>`;}).join(''):empty('users','Här börjar er gemensamma berättelse.','Dela din första seger, en reflektion eller en bild från dagens vana.','new-post','Skriv första inlägget')}</div></div><aside class="side-col">${squadMini()}<div class="card"><span class="eyebrow">Accountability</span><h3 style="margin:13px 0 10px">Fira att du dök upp.</h3><p class="muted" style="font-size:12px;line-height:1.8">Det behöver inte vara ett personbästa. Ett ärligt steg är värt att dela.</p><p class="fitness-hint space">${mode==='demo'||social.activityReady?'Vanor, pass och utmaningar delas automatiskt när de sparas.':'Automatisk delning aktiveras med databasuppdateringen.'} Lägg till en bild på ditt inlägg. Spegelbilder, privata mål och anteckningar stannar hos dig.</p>${button(I('camera')+' Dela en bild','new-post','btn secondary full space')}</div></aside></div>`;}
function profileView(){if(tab==='private')return fitness.nofapCard();const xp=D.totalXP(state),l=D.levelInfo(xp),banner=`<div class="profile-banner">${landscape()}<div class="flex">${avatar(state.profile.name,'large')}<div><span class="eyebrow" style="color:var(--gold)">${esc(state.profile.title||tier())}</span><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.bio)}</p></div>${button(I('edit')+' Redigera','edit-profile','btn secondary')}</div></div><div class="settings-row profile-lang"><div><h3>Språk</h3><p>Välj appens språk.</p></div>${langSwitch()}</div>`;
 if(tab==='body'){const entries=[...state.body].sort((a,b)=>b.date.localeCompare(a.date)),weights=entries.filter(e=>e.weight);return `${banner}<div class="section-head"><h2>Din kropp. Din utveckling.</h2>${button(I('plus')+' Dagens bild','new-body','btn ghost')}</div>${notice('Bilder och mått här är privata. De publiceras aldrig automatiskt i squadflödet.')}${weights.length?`<section class="card space"><div class="flex between"><div><span class="eyebrow">Din viktutveckling</span><h2 style="margin-top:9px">${weights[0].weight} <small class="muted">kg</small></h2></div><span class="muted" style="font-size:11px">${weights.length} mätningar</span></div>${weightChart(weights)}</section>`:''}<div class="section-head space"><span class="muted" style="font-size:11px">${entries.length} sparade ögonblick</span>${button('Jämför bilder '+I('arrow'),'compare','btn ghost',entries.filter(e=>e.photo).length<2?'disabled':'')}</div>${entries.length?`<div class="photo-grid">${entries.map(e=>`<button class="photo-tile" data-action="body:${e.id}">${e.photo?`<img data-photo="${esc(e.photo)}" alt="Privat progressbild ${esc(e.date)}" loading="lazy">`:`<div style="height:100%;display:grid;place-items:center;color:var(--muted)">${I('scale')}</div>`}<span>${dayLabel(e.date,{day:'numeric',month:'long'})}<small>${e.weight?esc(e.weight)+' kg':''}${e.waist?' · '+esc(e.waist)+' cm midja':''}</small></span></button>`).join('')}<button class="photo-tile photo-add" data-action="new-body">${I('camera')}Lägg till ett ögonblick</button></div>`:empty('camera','Börja din visuella resa.','Ta en bild i samma ljus och vinkel när det passar dig. Följ din egen utveckling över tid.','new-body','Spara din första bild')}`;}
 if(tab==='journal'){const ownPosts=(mode==='demo'?demoPosts():social.posts).filter(p=>p.user_id===selfId()&&p.image_path),photos=[...state.body.filter(x=>x.photo).map(x=>({...x,private:true})),...ownPosts.map(p=>({id:p.id,date:p.created_at.slice(0,10),photo:p.image_path,private:false}))].sort((a,b)=>b.date.localeCompare(a.date));return `${banner}<div class="section-head"><h2>Photo Evidence Journal</h2>${I('image')}</div><p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:22px">Ett visuellt minne av alla gånger du valde att dyka upp.</p>${photos.length?`<div class="photo-grid">${photos.map(e=>`<button class="photo-tile" data-action="${e.private?'body:'+e.id:'view-photo:'+e.photo}"><img data-photo="${esc(e.photo)}" alt="Minne från ${e.date}" loading="lazy"><span>${dayLabel(e.date)}<small>${e.private?'Privat ögonblick':'Delat med squadet'}</small></span></button>`).join('')}</div>`:empty('image','Din berättelse, i bilder.','Kroppstrackerns bilder och dina egna bildinlägg samlas här.','new-body','Spara ett ögonblick')}`;}
 if(tab==='reflections')return `${banner}<div class="section-head"><h2>En stund att se tillbaka.</h2>${button(I('plus')+' Reflektera','reflection','btn ghost')}</div>${state.reflections.length?[...state.reflections].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article class="card reflection-card"><div class="flex between"><span class="eyebrow">VECKAN ${dayLabel(D.weekKey(r.date))}</span><span class="mood">${['🌧️','🌥️','🌤️','☀️','✨'][r.mood-1]}</span></div><h3 style="margin-top:20px">Det här tar jag med mig</h3><p>${esc(r.win)}</p><h3 style="margin-top:20px">Nästa lilla steg</h3><p class="muted">${esc(r.next)}</p>${button('Redigera reflektion','reflection:'+r.id,'btn ghost space')}</article>`).join(''):empty('book','Lär av veckan som gick.','Några ärliga meningar hjälper dig upptäcka vad som fungerar och vad du vill ändra.','reflection','Skriv din första reflektion')}`;
 if(tab==='wrapped'){const count=D.completedHabits(state),perfect=Object.keys(state.history).filter(d=>D.progress(state,d).perfect).length,stat=D.stats(state),best=Object.entries(stat).sort((a,b)=>b[1]-a[1])[0];return `<section class="card wrapped"><span class="eyebrow">BEYOND SELF · DIN RESA HITTILLS</span><h2>Du dök upp.<br>Det förändrade allt.</h2><p>${esc(state.profile.name)}, här är spåren av alla små beslut som gjorde dig till en starkare version av dig själv.</p>${character(l.level,false,state.profile.character)}<div class="wrapped-stats"><div><strong>${fmt(count)}</strong><small>genomförda vanor</small></div><div><strong>${D.bestStreak(state)}</strong><small>dagar · längsta streak</small></div><div><strong>${fmt(xp)}</strong><small>XP på din resa</small></div><div><strong>${perfect}</strong><small>perfekta dagar</small></div></div><h3>${count?best[0]+' blev ditt starkaste område.':'Din första lilla seger väntar.'}</h3><div class="heatmap">${Array.from({length:90},(_,i)=>{const d=D.shiftDate(state.expedition.start,i),p=D.progress(state,d);return `<div class="${p.perfect?'full':p.done?'half':''}" title="${d}: ${p.done}/${p.total}"></div>`;}).join('')}</div><p>Varje ruta är en dag i din expedition.<br>${state.body.length} bilder. ${state.reflections.length} reflektioner. Din berättelse.</p><div class="quote">”Det är de små sakerna, upprepade, som gör dig till den du vill vara.”</div>${button(I('download')+' Spara din Wrapped','download-wrapped','btn')}</section>`;}
 const s=cstats();return `${banner}${fitness.rankCard()}<div class="dashboard"><div class="main-col"><section class="card"><div class="section-head"><h2>Din karaktär</h2><span class="level-badge">LEVEL ${l.level}</span></div><div class="profile-hero-character">${character(l.level,true,state.profile.character)}</div><div class="character-caption"><h3>${esc(state.profile.characterName||F.characters.find(c=>c.id===state.profile.character)?.name||'Aurora Ranger')}</h3>${button(I('edit')+' Välj & anpassa karaktär','fit:characters','btn secondary space')}</div><div class="text-right xp-track"><b>${fmt(xp)} totalt XP</b><span>${fmt(l.next-xp)} XP till nästa nivå</span></div>${bar(l.ratio)}<div class="stats-bars">${Object.entries(s).map(([k,v],i)=>`<div class="stat-line"><span>${k}</span>${bar(v/Math.max(500,...Object.values(s)),['#a7bcfa','#88d3cf','#ffca84','#c4b3ec','#ead398','#f3acc4','#e1b6d8'][i])}<b>${fmt(v)}</b></div>`).join('')}</div><p class="muted" style="font-size:11px;line-height:1.7;margin-top:14px">Stats växer med vanor, pass och utmaningar, och även med dina skill-nivåer och uppnådda mål.</p>${button('Utforska ditt skill tree '+I('arrow'),'nav:journey:skills','btn ghost space')}</section><div class="mini-stats"><div class="mini-stat">${I('flame')}<strong>${D.bestStreak(state)}</strong><span>Längsta streak</span></div><div class="mini-stat">${I('gem')}<strong>${D.achievements(state).filter(a=>a.unlocked).length}</strong><span>Achievements</span></div><div class="mini-stat">${I('camera')}<strong>${state.body.length}</strong><span>Sparade ögonblick</span></div></div></div><aside class="stack"><section class="card"><span class="eyebrow">Evolution system</span><h3 style="margin:15px 0 12px">${tier()}</h3><p class="muted" style="font-size:12px;line-height:1.8">Din karaktär förändras med dig. Nya färger, detaljer och rustningar låses upp vid level 6, 11 och 16.</p>${[1,6,11,16].map((n,i)=>`<div class="settings-row"><div class="flex">${I(l.level>=n?'check':'lock')}<div><h3>${['Vandrare','Frostvandrare','Norrskensväktare','Vinterlegend'][i]}</h3><p>Level ${n}</p></div></div>${l.level>=n?'<span class="pill">Upplåst</span>':''}</div>`).join('')}</section>${mode!=='cloud'?`<section class="card"><h3>Ta med din resa.</h3><p class="muted" style="font-size:12px;line-height:1.8;margin:12px 0">Ett eget konto ger dig samma expedition på alla dina enheter.</p>${button('Anslut konto '+I('arrow'),'auth','btn secondary full')}</section>`:''}</aside></div>`;}
function weightChart(weights){const arr=[...weights].reverse(),min=Math.min(...arr.map(x=>x.weight))-.5,max=Math.max(...arr.map(x=>x.weight))+.5,pts=arr.map((w,i)=>`${20+i/(Math.max(1,arr.length-1))*460},${130-(w.weight-min)/(max-min)*110}`);return `<svg class="measure-chart" viewBox="0 0 500 150" role="img" aria-label="Vikt från ${arr[0].weight} till ${arr.at(-1).weight} kilogram"><path d="M20 130h460M20 75h460M20 20h460" stroke="#30423e" fill="none" stroke-dasharray="3 5"/><polyline points="${pts.join(' ')}" fill="none" stroke="#c6e7df" stroke-width="2"/>${pts.map(p=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="3" class="weight-point"/>`).join('')}</svg>`;}

async function commit(mutator,message){if(busy)throw Error('En ändring sparas redan. Vänta ett ögonblick.');busy=true;const before=structuredClone(state);try{mutator(state);D.normalizeState(state,mode==='cloud'?cloud.user?.created_at:undefined,mode==='demo');if(mode==='cloud'){syncStatus='Sparar…';render();state=await saveWithRecovery(state,{save:cloud.save,load:cloud.load,mutate:mutator,normalize:s=>D.normalizeState(s,cloud.user?.created_at,false)});}else persistLocal();syncStatus='';render();if(message)toast(message);}catch(e){state=before;syncStatus='Kunde inte spara';render();throw e;}finally{busy=false;}}
async function refreshSocial(){const request=++socialRequest;try{const nextSquad=await cloud.mySquad(),next=await cloud.social(nextSquad);if(request!==socialRequest)return;squad=nextSquad;social=next;socialError='';}catch(e){if(request!==socialRequest)return;socialError='Flödet kunde inte uppdateras. Dina sparade framsteg finns kvar.';}if(route==='squad')render();}
function acceptPost(post){socialRequest++;social.posts=[post,...social.posts.filter(p=>p.id!==post.id)];}

async function photoDB(){return await new Promise((resolve,reject)=>{const r=indexedDB.open('winter-arc-photos',1);r.onupgradeneeded=()=>r.result.createObjectStore('photos');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function localPhoto(op,id,value){const db=await photoDB();try{return await new Promise((resolve,reject)=>{const t=db.transaction('photos',op==='get'?'readonly':'readwrite'),s=t.objectStore('photos');let result;const req=op==='get'?s.get(id):op==='delete'?s.delete(id):s.put(value,id);req.onsuccess=()=>result=req.result;t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error);});}finally{db.close();}}
const blobUrls=new Map();
async function getPhoto(path,refresh=false){if(mode==='cloud')return cloud.imageUrl(path,refresh);if(blobUrls.has(path))return blobUrls.get(path);const blob=await localPhoto('get',path);if(!blob)return '';const url=URL.createObjectURL(blob);blobUrls.set(path,url);return url;}
async function hydrateImages(){await Promise.all([...document.querySelectorAll('img[data-photo]')].map(image=>displayPhoto(image,getPhoto)));}
async function preparePhoto(file){if(!file)return null;if(!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(file.type))throw Error('Välj en bild i JPEG, PNG eller WebP. Exportera HEIC som JPEG om den inte kan öppnas.');if(file.size>20*1024*1024)throw Error('Bilden får vara högst 20 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1600/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return await new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(Error('Bilden kunde inte läsas.')),'image/jpeg',.85));}catch{throw Error('Bilden kunde inte läsas. Prova JPEG eller PNG.');}finally{URL.revokeObjectURL(url);}}
const photoPreparations=new WeakMap();
function formPhoto(f){const file=f.querySelector('input[type=file]')?.files?.[0];if(!file)return Promise.resolve(null);const old=photoPreparations.get(f);if(old?.file===file)return old.promise;const promise=preparePhoto(file);photoPreparations.set(f,{file,promise});return promise;}
async function storePhoto(blob,kind){if(!blob)return null;if(mode==='cloud')return cloud.upload(blob,kind);const id=`local-${mode}-${D.uid()}`;await localPhoto('put',id,blob);return id;}
async function deletePhoto(path){if(!path)return;if(mode==='cloud')await cloud.removeImage(path);else{await localPhoto('delete',path);if(blobUrls.has(path)){URL.revokeObjectURL(blobUrls.get(path));blobUrls.delete(path);}}}
function closeModal(restore=true,animate=false){if(animate&&document.querySelector('.form[data-submitting]'))return;const root=$('#modal-root'),overlay=root.firstElementChild,focus=modalFocus;const finish=()=>{if(root.firstElementChild!==overlay)return;root.innerHTML='';document.body.style.overflow='';if(restore)focus?.focus({preventScroll:true});};if(animate&&overlay)dismissWithMotion(overlay,finish);else finish();}
function modal(title,html){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2>${button(I('close'),'close','icon-btn','aria-label="Stäng"')}</div>${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input:not([type=file]),.modal textarea,.modal button')?.focus({preventScroll:true}));hydrateImages();}
function form(id,html,submit='Spara'){return `<form class="form" id="${id}">${html}<p class="form-error" role="alert"></p><button class="btn full" type="submit">${submit}</button></form>`;}
function categoryOptions(selected){return Object.entries(D.categories).map(([k,c])=>`<option value="${k}" ${k===selected?'selected':''}>${c.name} · ${c.stat}</option>`).join('');}
function habitModal(h=null){if(h?.pending)h={...h,...h.pending};modal(h?.id?'Forma din vana':'Ett litet steg börjar här',`<p class="intro">Gör det så enkelt att du kan dyka upp även en svår dag.</p>${form('habit-form',`<input type="hidden" name="id" value="${h?.id||''}"><label>Vad vill du göra?<input name="name" required maxlength="70" placeholder="Exempel: Läs tio sidor" value="${esc(h?.name||'')}"></label><label>Livsområde<select name="category" ${h?.templateId?'disabled':''}>${categoryOptions(h?.category||'discipline')}</select>${h?.templateId?`<input type="hidden" name="category" value="${h.category}">`:''}</label><div class="grid2"><label>Dagligt mål<input name="target" type="number" required min="1" max="100000" step="1" value="${h?.target||1}"></label><label>Enhet<input name="unit" ${h?.templateId?'readonly':''} required maxlength="20" value="${esc(h?.unit||'gång')}"></label></div><label>Planerad tid · minuter<input name="durationMinutes" type="number" inputmode="numeric" min="1" max="120" step="1" value="${h?.durationMinutes||(h?.unit==='min'?Math.min(120,h.target):h?.unit==='pass'?30:10)}" required><span class="hint">2 XP per minut när målet är klart. 10 min = 20 XP, 60 min = 120 XP, före dagsgränsen. Tid och rank är olika saker.</span></label><label>Min vanekoppling<input name="cue" maxlength="180" placeholder="Efter [det jag redan gör] ska jag…" value="${esc(h?.cue||'')}"><span class="hint">En tydlig signal gör det lättare att börja.</span></label><fieldset style="border:0;padding:0;margin:0"><legend class="field-label">Vilka dagar?</legend><div class="day-picker">${[1,2,3,4,5,6,0].map((n,i)=>`<label><input type="checkbox" name="days" value="${n}" ${!h||h.days.includes(n)?'checked':''}><span>${['Mån','Tis','Ons','Tor','Fre','Lör','Sön'][i]}</span></label>`).join('')}</div></fieldset><span class="hint">${h?'Mål och schema ändras från imorgon. Bibliotekets enhet och stat följer aktiviteten. Dagens och tidigare dagars mål behålls.':'Välj en realistisk tid. Samma vana registreras en gång per dag. Tidsbaserade vanor delar ett tak på 240 XP per dag.'}</span>`,h?.id?'Spara vanan':'Lägg till vana')}${h?.id?button('Arkivera vana','archive:'+h.id,'destructive space'):''}`);}
function progressModal(h){const value=state.history[today()]?.entries[h.id]?.value||0;modal(h.name,`<p class="intro">${esc(h.cue||'Ett litet steg för den du vill bli.')}</p>${form('progress-form',`<input name="id" type="hidden" value="${h.id}"><div class="counter" id="progress-value">${value} / ${h.target} <small>${esc(h.unit)}</small></div><label>Hur långt har du kommit?<input name="value" type="range" min="0" max="${h.target}" step="1" value="${value}"></label>`,value>=h.target?'Spara ändring':'Registrera framsteg')}${value<h.target?button(I('check')+' Markera hela målet klart','finish:'+h.id,'btn secondary full space'):button('Ångra dagens registrering','undo:'+h.id,'btn secondary full space')}`);}
function goalModal(g=null){modal(g?'Uppdatera ditt mål':'Ett mål att växa mot',form('goal-form',`<input type="hidden" name="id" value="${g?.id||''}"><label>Mitt mål<input name="name" required maxlength="100" value="${esc(g?.name||'')}" placeholder="Exempel: Genomföra 40 träningspass"></label><label>Livsområde<select name="category">${categoryOptions(g?.category||'strength')}</select></label><div class="grid2"><label>Målvärde<input name="target" required type="number" min="1" max="1000000" value="${g?.target||30}"></label><label>Nuvarande värde<input name="current" required type="number" min="0" max="1000000" value="${g?.current||0}"></label></div><label>Enhet<input name="unit" required maxlength="30" value="${esc(g?.unit||'pass')}"></label><label>Måldatum<input name="deadline" type="date" required value="${g?.deadline||D.shiftDate(today(),60)}"></label>`));}
function reflectionModal(id){const r=id?state.reflections.find(x=>x.id===id):state.reflections.find(x=>D.weekKey(x.date)===D.weekKey(today()));modal('Veckans reflektion',`<p class="intro">Du behöver inte ha alla svar. Ge dig själv några ärliga minuter.</p>${form('reflection-form',`<input name="id" type="hidden" value="${r?.id||''}"><label>Hur har veckan känts?<select name="mood">${['🌧️ Tung','🌥️ Utmanande','🌤️ Okej','☀️ Bra','✨ Riktigt bra'].map((m,i)=>`<option value="${i+1}" ${Number(r?.mood||4)===i+1?'selected':''}>${m}</option>`).join('')}</select></label><label>Vad fungerade? Vad var svårt?<textarea name="win" required maxlength="2000" placeholder="En liten seger, en lärdom, något jag vill förstå…">${esc(r?.win||'')}</textarea></label><label>Mitt nästa lilla steg<textarea name="next" required maxlength="1000" placeholder="Nästa vecka gör jag det lättare genom att…">${esc(r?.next||'')}</textarea></label>`,r?'Uppdatera reflektion':'Spara reflektion')}`);}
function bodyModal(entry){if(entry){modal(dayLabel(entry.date,{day:'numeric',month:'long',year:'numeric'}),`${entry.photo?`<img data-photo="${esc(entry.photo)}" alt="Din privata progressbild" style="width:100%;max-height:55dvh;object-fit:contain;border-radius:14px">`:''}<div class="metric-list space">${entry.weight?`<div class="metric-line"><span class="muted">Vikt</span><strong>${entry.weight} kg</strong></div>`:''}${entry.waist?`<div class="metric-line"><span class="muted">Midja</span><strong>${entry.waist} cm</strong></div>`:''}</div><p class="muted space" style="font-size:12px;line-height:1.8">${esc(entry.note)}</p><div class="space">${notice('Privat. Synlig bara för dig.')}</div>${button('Ta bort detta ögonblick','confirm-body-delete:'+entry.id,'destructive space')}`);return;}
 modal('Ett ögonblick av din utveckling',`${notice('Privat för dig. Bilder komprimeras och platsmetadata tas bort vid import.')}${form('body-form',`<label>Datum<input name="date" type="date" required max="${today()}" value="${today()}"></label><label>Progressbild (valfri)<input name="photo" class="file-input" type="file" accept="image/*"><span class="hint">Samma ljus och vinkel gör bilder lättare att jämföra.</span></label><div class="grid2"><label>Vikt, kg (valfritt)<input name="weight" type="number" step="0.1" min="20" max="500" inputmode="decimal" placeholder="—"></label><label>Midja, cm (valfritt)<input name="waist" type="number" step="0.1" min="30" max="300" inputmode="decimal" placeholder="—"></label></div><label>En tanke att spara<textarea name="note" maxlength="500" placeholder="Hur känns det idag?"></textarea></label>`,'Spara privat ögonblick')}`);}
function authModal(){if(!developmentModes){modal('Ditt Beyond Self-konto',`<p class="intro">Logga in med Google för att hämta din profil och dina sparade framsteg.</p>${button('Fortsätt med Google','google','btn full',!cloud.googleReady?'disabled':'')}`);return;}modal('Ta med din expedition',`<div class="auth-modal"><span class="brand-mark"><img src="./icon-192.png" alt=""></span><h2>Beyond Self.<br>Var du än är.</h2><p>Ett eget konto. Dina vanor och minnen.<br>Ditt squad, med dig hela vägen.</p><div class="auth-options">${button('<span class="google-logo">G</span> Fortsätt med Google','google','btn full',!cloud.googleReady?'disabled':'')}${!cloud.googleReady?notice(cloud.configured?'Databasen är ansluten. Google-inloggning väntar på att OAuth-klienten aktiveras.':'Google-inloggning väntar på ert nya Supabase-projekt. Demoläget går att prova redan nu.'):''}${button('Börja min egen lokala expedition','start-local','btn secondary full')}${button('Utforska demoläget','start-demo','btn ghost full')}</div><small>${mode==='demo'?'Exempeldata flyttas aldrig till ditt konto.':'Din lokala expedition sparas på den här enheten.'}</small></div>`);}
function settingsModal(){modal('Din expedition, dina val',`<div class="settings-row"><div><h3>Språk</h3><p>Välj appens språk.</p></div>${langSwitch()}</div><div class="settings-theme"><h3>Färgtema</h3><p>Välj ett vintertema. Sparas på den här enheten.</p>${themePicker()}</div>${installed()?'':`<section class="install-cta"><span class="eyebrow">ALLTID NÄRA</span><h3>Beyond Self. På hemskärmen.</h3><p>Öppna som en egen app på din iPhone.</p>${button(I('plus')+' Lägg till som app','install','btn full')}</section>`}<div class="settings-row"><div><h3>Expeditionens start</h3><p>${state.expedition.start} · 90 dagar. Senare konton börjar på sin registreringsdag.</p></div></div><div class="settings-row"><div><h3>Konto & lagring</h3><p>${mode==='cloud'?'Google-konto · molnsynkat':mode==='demo'?'Demoläge · exempeldata på enheten':'Lokal expedition · bara den här enheten'}</p></div>${button(mode==='cloud'?'Logga ut':'Anslut','auth','btn ghost')}</div><div class="settings-row"><div><h3>Tidszon</h3><p>${esc(state.timezone)} · dagarna följer denna tidszon</p></div></div>${installed()?'':`<div class="settings-row"><div><h3>Installera på iPhone</h3><p>Lägg Beyond Self på din hemskärm.</p></div>${button(I('arrow'),'install','icon-btn','aria-label="Visa installationsguide"')}</div>`}<div class="settings-row"><div><h3>Din data</h3><p>Exportera din journal och dina framsteg som JSON. Bilder lagras separat.</p></div>${button(I('download'),'export','icon-btn','aria-label="Exportera min data"')}</div><div class="settings-row"><div><h3>Ny version</h3><p>Appen söker automatiskt efter uppdateringar.</p></div>${button(I('refresh'),'check-update','icon-btn','aria-label="Sök efter uppdatering"')}</div>${mode==='cloud'?button('Logga ut från denna enhet','logout','btn secondary full space'):button(mode==='demo'?'Börja min egen expedition':'Öppna demoläget',mode==='demo'?'start-local':'start-demo','btn secondary full space')}<p class="muted" style="font-size:10px;line-height:1.8;margin-top:20px">Beyond Self 2.0 · Utveckling i din egen takt. Kroppsmått är frivilliga. Appen ger inga medicinska bedömningar.</p>`);}
function inviteModal(){if(mode==='demo'){modal('Ditt framtida squad',`${notice('Det här är demoläget. Riktiga inbjudningar aktiveras när ert Supabase-projekt är anslutet.')}<p class="intro space">Skapa ett privat squad, dela en inbjudningskod och låt vännerna ansluta med sina egna Google-konton.</p>${button('Anslut eget konto','auth','btn full')}`);return;}if(mode!=='cloud'){authModal();return;}if(squad){modal('Bjud in till '+esc(squad.name),`<p class="intro">En inbjudningskod ger tillgång till squadets flöde och leaderboard. Dela den med dina vänner.</p><div id="invite-code" class="counter">Hämtar…</div>${button('Kopiera kod','copy-invite','btn full space')}`);cloud.invite(squad.id).then(code=>{if($('#invite-code'))$('#invite-code').textContent=code;}).catch(e=>toast(e.message));return;}
 modal('Hitta ditt squad',`${form('create-squad-form','<label>Starta ett nytt squad<input name="name" required maxlength="40" placeholder="Exempel: The Northbound"></label>','Skapa squad')}<div style="border-top:1px solid var(--line);margin:25px 0"></div>${form('join-squad-form','<label>Eller gå med via inbjudningskod<input name="code" required minlength="12" maxlength="80" placeholder="Klistra in din kod" autocomplete="off"></label>','Gå med i squad')}`);}
const quickActions=[['workout','dumbbell','Starta träningspass','Ett tomt pass i Styrkehubben'],['cardio','run','Logga kondition','Löpning, promenad, cykel och mer'],['habit','list','Ny vana','Ett litet steg att upprepa'],['post','users','Dela med ditt squad','Ett framsteg eller en tanke'],['settings','settings','Inställningar','Språk, konto och installation']];
function quickModal(){modal('Vad vill du göra?',`<div class="quick-sheet">${quickActions.map(([k,i,t,d])=>`<button class="quick-row" data-action="quick:${k}"><span class="habit-icon">${I(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${I('chevron')}</button>`).join('')}</div>`);}
async function quickAction(kind){if(!kind)return quickModal();if(kind==='settings')return settingsModal();if(kind==='habit')return habitModal();if(kind==='post')return mode==='cloud'&&!squad?inviteModal():postModal();closeModal();fitness.action(['section','strength']);navTo('training');if(kind==='cardio')await strength.action(['cardio']);else if(!state.strength?.active)await strength.action(['start']);}
function postModal(){const draft=readPostDraft();modal('Ett steg värt att dela',`${notice('Inlägget och eventuell bild blir synliga för alla i ditt squad.')}${form('post-form',`<label>Din berättelse<textarea name="body" ${draft.attempted?'readonly':''} required maxlength="2000" placeholder="Vad gjorde du för dig själv idag?">${esc(draft.body||'')}</textarea></label><label>Accountability-bild (valfri)<input name="photo" type="file" class="file-input" accept="image/*"></label>`,'Dela med squadet')}${draft.attempted?'<p class="fitness-hint">Ett tidigare sparförsök behöver bekräftas. Försök igen med samma inlägg för att undvika dubbletter.</p>':''}${draft.image_path?'<p class="fitness-hint">Din tidigare valda bild är sparad med utkastet.</p>':''}`);}
function postPhotoModal(id){modal('Lägg till en bild',`${notice('Bilden delas med ditt squad. Dina privata spegelbilder delas aldrig automatiskt.')}${form('post-photo-form',`<input type="hidden" name="post" value="${esc(id)}"><label>Bild till inlägget<input name="photo" type="file" accept="image/*" required></label>`,'Spara bilden')}`);}
function onboarding(){modal('Vem vill du bli?',`<p class="intro">Din expedition börjar ${state.expedition.start}. Välj några små steg att börja med. Du kan alltid ändra och lägga till fler.</p>${form('onboarding-form',`<label>Vad ska vi kalla dig?<input name="name" required maxlength="40" value="${esc(mode==='cloud'?cloud.user?.user_metadata?.full_name?.split(' ')[0]||'':'')}" placeholder="Ditt namn"></label><div class="onboarding-grid">${D.library.slice(0,6).map((h,i)=>`<label class="onboarding-choice"><input type="checkbox" name="habits" value="${i}" ${i<3?'checked':''}>${esc(h[0])}</label>`).join('')}</div><span class="hint">Börja gärna med 1–3 vanor. Det lilla du gör slår det stora du planerar.</span>`,'Börja min expedition')}`);}

async function action(a){const [cmd,...parts]=a.split(':'),arg=parts.join(':');
 switch(cmd){
 case 'hub':await strength.action(parts);break;
 case 'fit':await fitness.action(parts);break;
 case 'friend':await friends.action(parts);break;
 case 'skt':skillTree.action(parts);break;
 case 'nav':navTo(parts[0],parts[1]||'');break;
 case 'tab':tab=arg;filter='all';render();break;
 case 'filter':filter=arg;render();break;
 case 'day':selectedDay=arg;render();break;
 case 'close':closeModal(true,true);break;
 case 'new-habit':habitModal();break;
 case 'edit-habit':habitModal(state.habits.find(h=>h.id===arg));break;
 case 'habit':{const h=state.habits.find(h=>h.id===arg),e=state.history[today()]?.entries[h.id];if(h.target===1){await complete(h.id,e?.value>=h.target?0:h.target);}else progressModal(h);break;}
 case 'finish':await complete(arg,state.habits.find(h=>h.id===arg).target);closeModal();break;
 case 'undo':await complete(arg,0);closeModal();break;
 case 'archive':await commit(s=>D.archiveHabit(s,arg,today()),'Vanan har arkiverats. Tidigare framsteg finns kvar.');closeModal();break;
 case 'library':{const h=D.makeHabit(D.library[Number(arg)],today()>state.expedition.start?today():state.expedition.start);habitModal({...h,id:'',durationMinutes:h.unit==='min'?Math.min(120,h.target):h.unit==='pass'?30:10});break;}
 case 'claim':await commit(s=>D.claimQuest(s,arg,today()),'Uppdrag slutfört. Bonus-XP till din karaktär!');break;
 case 'new-goal':goalModal();break;
 case 'goal':goalModal(state.goals.find(g=>g.id===arg));break;
 case 'reflection':reflectionModal(arg);break;
 case 'new-body':bodyModal();break;
 case 'body':bodyModal(state.body.find(x=>x.id===arg));break;
 case 'confirm-body-delete':modal('Ta bort detta ögonblick?',`<p class="intro">Bilden och måtten tas bort från din journal. Detta kan inte ångras.</p>${button('Ta bort ögonblick','delete-body:'+arg,'btn danger full')}`);break;
 case 'delete-body':{const e=state.body.find(x=>x.id===arg);await commit(s=>s.body=s.body.filter(x=>x.id!==arg));await deletePhoto(e.photo);closeModal();toast('Ögonblicket har tagits bort.');break;}
 case 'compare':{const es=state.body.filter(x=>x.photo).sort((a,b)=>a.date.localeCompare(b.date));if(es.length<2)return;modal('Se din egen utveckling',`${form('compare-form',`<div class="grid2"><label>Första bilden<select name="first">${es.map(e=>`<option value="${e.id}">${dayLabel(e.date)}</option>`).join('')}</select></label><label>Andra bilden<select name="second">${es.map((e,i)=>`<option value="${e.id}" ${i===es.length-1?'selected':''}>${dayLabel(e.date)}</option>`).join('')}</select></label></div>`,'Visa jämförelse')}<div id="comparison" class="comparison space">${[es[0],es.at(-1)].map(e=>`<div><img data-photo="${esc(e.photo)}" alt="Progressbild ${e.date}"><p>${dayLabel(e.date)}</p></div>`).join('')}</div>`);break;}
 case 'view-photo':modal('Ett ögonblick från din resa',`<img data-photo="${esc(arg)}" alt="Bild från din expedition" style="width:100%;max-height:65dvh;object-fit:contain">`);break;
 case 'reward':{const n=Number(arg),rewards={3:'En välförtjänt paus',6:'Frostvandrare',11:'Norrskensväktare',16:'Vinterlegend'};if(D.levelInfo(D.totalXP(state)).level<n||state.rewards.includes(n))return;await commit(s=>{s.rewards.push(n);s.profile.title=rewards[n];},'Belöning upplåst: '+rewards[n]);break;}
 case 'edit-profile':modal('Din profil',form('profile-form',`<label>Namn<input name="name" required maxlength="40" value="${esc(state.profile.name)}"></label><label>Profilbild<input type="file" name="avatar" accept="image/*"></label><span class="hint">Välj från ditt bildbibliotek. Bilden är privat på din profil.</span><div class="grid2"><label>Kroppsvikt · kg<input name="weight" type="number" inputmode="decimal" min="25" max="400" step="0.1" value="${state.profile.weight||''}"></label><label>Längd · cm<input name="height" type="number" inputmode="numeric" min="100" max="250" value="${state.profile.height||''}"></label></div><label>Din bio<textarea name="bio" maxlength="200">${esc(state.profile.bio)}</textarea></label><label>Titel<select name="title">${[...new Set(['The beginning',tier(),...state.rewards.map(n=>({3:'En välförtjänt paus',6:'Frostvandrare',11:'Norrskensväktare',16:'Vinterlegend'}[n])),state.profile.title])].map(t=>`<option ${t===state.profile.title?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`));break;
 case 'settings':settingsModal();break;
 case 'auth':authModal();break;
 case 'google':await cloud.login();break;
 case 'start-local':await switchMode('local');break;
 case 'start-demo':if(developmentModes)await switchMode('demo');break;
 case 'reload':location.reload();break;
 case 'logout':await cloud.logout();await switchMode('local');break;
 case 'invite':inviteModal();break;
 case 'copy-invite':await navigator.clipboard.writeText($('#invite-code').textContent);toast('Inbjudningskoden är kopierad.');break;
 case 'new-post':postModal();break;
 case 'quick':await quickAction(arg);break;
 case 'lang':if(setLanguage(arg))location.reload();break;
 case 'theme':if(setTheme(arg))settingsModal();break;
 case 'refresh-social':await refreshSocial();break;
 case 'post-photo':postPhotoModal(arg);break;
 case 'retry-photo':{const post=(mode==='demo'?demoPosts():social.posts).find(p=>p.id===arg),image=[...document.querySelectorAll('.post-image')].find(i=>i.dataset.photo===post?.image_path);if(image)await displayPhoto(image,path=>getPhoto(path,true));break;}
 case 'react':{const [postId,kind]=parts;const post=(mode==='demo'?demoPosts():social.posts).find(p=>p.id===postId);if(!post)return;const active=(post.reactions||[]).some(r=>r.user_id===selfId()&&r.kind===kind);if(mode!=='demo')await cloud.react(postId,kind,active);socialRequest++;post.reactions=(post.reactions||[]).filter(r=>!(r.user_id===selfId()&&r.kind===kind));if(!active)post.reactions.push({user_id:selfId(),kind});if(mode==='demo')localStorage.setItem('arc-demo-social',JSON.stringify(demoSocial));render();break;}
 case 'delete-post':modal('Hantera ditt inlägg',`<p class="intro">Vill du ta bort inlägget och eventuell bild från squadets flöde?</p>${button('Ta bort inlägg','remove-post:'+arg,'btn danger full')}`);break;
 case 'remove-post':{const p=(mode==='demo'?demoPosts():social.posts).find(p=>p.id===arg);if(!p)return;if(mode==='demo'){demoSocial=demoSocial.filter(p=>p.id!==arg);localStorage.setItem('arc-demo-social',JSON.stringify(demoSocial));}else{await cloud.removePost(arg);socialRequest++;social.posts=social.posts.filter(p=>p.id!==arg);}closeModal();render();toast('Inlägget har tagits bort.');if(p.image_path)try{await deletePhoto(p.image_path);}catch{toast('Inlägget är borttaget. Bildfilen kunde inte rensas just nu.');}break;}

 case 'new-mission':if(mode==='demo'){modal('Squad mission',notice('Riktiga gruppuppdrag skapas när ert Supabase-projekt är anslutet. Det befintliga demouppdraget visar hur alla i gruppen bidrar.'));break;}modal('Ett gemensamt veckomål',form('mission-form',`<label>Uppdragets namn<input name="name" required maxlength="80" placeholder="Exempel: 100 små segrar"></label><label>Antal genomförda vanor tillsammans<input name="target" required type="number" min="1" max="10000" value="100"></label><span class="hint">Uppdraget räknar alla genomförda vanor den här kalenderveckan och avslutas på söndag.</span>`,'Skapa squad mission'));break;
 case 'notifications':{const qs=D.quests(state,today()).filter(q=>q.current>=q.target&&!state.claims[q.id]);modal('Små saker att fira',`${qs.length?qs.map(q=>`<div class="notification-row">${I('gift')}<div><strong>${q.name}</strong><small>Uppdraget är klart. Hämta dina ${q.xp} XP i expeditionen.</small></div></div>`).join(''):notice('Inga nya notiser just nu. Ditt nästa lilla steg väntar på startsidan.')}<div class="notification-row">${I('flame')}<div><strong>${D.streak(state,today())} dagars streak</strong><small>${D.progress(state,today()).perfect?'Alla dagens mål är klara. Ta en stund att fira.':'Nå alla dagens mål för att fortsätta din streak.'}</small></div></div>${button('Se uppdragen '+I('arrow'),'nav:journey','btn full space')}`);break;}
 case 'install':modal('Beyond Self på din iPhone',`<div class="stack"><p class="muted" style="font-size:12px;line-height:1.8">Öppna appens publicerade webbadress i Safari på din iPhone.</p>${[['1','Tryck på Dela','Fyrkanten med pilen uppåt i Safari.'],['2','Välj Lägg till på hemskärmen','Scrolla ner i delningsmenyn. Om valet Öppna som webbapp visas, låt det vara på.'],['3','Tryck på Lägg till','Beyond Self öppnas som en egen app från din hemskärm.']].map(([n,t,p])=>`<div class="flex"><span class="avatar">${n}</span><div><h3 style="font-size:13px">${t}</h3><p class="muted" style="font-size:11px;line-height:1.7;margin-top:5px">${p}</p></div></div>`).join('')}${notice('Nya versioner hämtas automatiskt. Om en uppdatering är redo får du välja att öppna den. Molnsynk behöver internet.')}</div>`);break;
 case 'sync':if(mode==='cloud'){const fresh=await cloud.load();if(fresh)state=fresh;applyPending();await refreshSocial();render();toast('Dina framsteg är uppdaterade.');}break;
 case 'export':download(`beyond-self-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Din data har exporterats. Bilder ingår inte i JSON-filen.');break;
 case 'download-wrapped':downloadWrapped();break;
 case 'check-update':{const reg=await navigator.serviceWorker?.getRegistration();if(reg){await reg.update();if(reg.waiting)queueUpdate(reg);else toast('Uppdateringskontroll genomförd.');}else toast('Uppdateringar aktiveras på den publicerade webbadressen.');break;}
 case 'apply-update':{const reg=await navigator.serviceWorker.getRegistration();reg?.waiting?.postMessage({type:'SKIP_WAITING'});break;}
 }
}
async function complete(id,value){const before=D.totalXP(state),level=D.levelInfo(before).level;await commit(s=>D.setProgress(s,id,value,today()));const gain=D.totalXP(state)-before;toast(D.levelInfo(D.totalXP(state)).level>level?'Ny nivå! Din karaktär växer med dig.':gain>0?`+${gain} XP · Ett steg närmare den du vill bli.`:'Dagens registrering har uppdaterats.');}
async function switchMode(next){if(!developmentModes&&next!=='cloud'){if(mode==='cloud')await cloud.logout();mode='guest';state=D.blankState();closeModal();render();return;}if(mode==='cloud'&&next!=='cloud')await cloud.logout();mode=next;localStorage.setItem('arc-mode',mode);state=readLocal()||(next==='demo'?D.seedDemo():D.blankState());squad=null;socialError='';socialRequest++;social={posts:[],members:[],missions:[]};applyPending();selectedDay=today();persistLocal();closeModal();navTo('today');if(next==='local'&&!state.onboarded)onboarding();}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadWrapped(){const count=D.completedHabits(state),xp=D.totalXP(state),level=D.levelInfo(xp).level;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><rect width="1080" height="1350" fill="#182a28"/><circle cx="540" cy="350" r="310" fill="#28473c"/><text x="540" y="110" text-anchor="middle" fill="#dfc594" font-family="sans-serif" font-size="22" letter-spacing="7">BEYOND SELF · WRAPPED</text><text x="540" y="230" text-anchor="middle" fill="#f0f3ec" font-family="sans-serif" font-weight="bold" font-size="64">Du dök upp.</text><text x="540" y="305" text-anchor="middle" fill="#f0f3ec" font-family="sans-serif" font-weight="bold" font-size="60">Det förändrade allt.</text><g transform="translate(300 330) scale(1.9)">${character(level,false,state.profile.character).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><text x="540" y="880" text-anchor="middle" fill="#c6e7df" font-family="sans-serif" font-size="32">${esc(state.profile.name)} · Level ${level}</text>${[[270,1010,fmt(count),'genomförda vanor'],[810,1010,fmt(xp),'intjänade XP'],[270,1180,D.bestStreak(state),'dagars längsta streak'],[810,1180,state.body.length,'sparade ögonblick']].map(([x,y,n,t])=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#c6e7df" font-family="sans-serif" font-weight="bold" font-size="64">${n}</text><text x="${x}" y="${y+45}" text-anchor="middle" fill="#a1b6af" font-family="sans-serif" font-size="21">${t}</text>`).join('')}<text x="540" y="1310" text-anchor="middle" fill="#809d92" font-family="sans-serif" font-size="16" letter-spacing="3">ETT LITET STEG. VARJE DAG.</text></svg>`;download(`beyond-self-wrapped-${today()}.svg`,svg,'image/svg+xml');toast('Din Wrapped har sparats som en delbar bild.');}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||document.querySelector('.form[data-submitting]'))return;const key=b.dataset.action;if(actionLocks.has(key))return;actionLocks.add(key);try{await action(key);}catch(error){console.error(error);const target=$('.form-error');if(target)target.textContent=error.message;else toast(error.message||'Något gick fel. Försök igen.');}finally{actionLocks.delete(key);}});
document.addEventListener('input',e=>{if(e.target.closest('#post-form')){const draft=readPostDraft();if(!draft.attempted){draft.body=e.target.closest('form').querySelector('[name=body]').value;localStorage.setItem(draftKey(),JSON.stringify(draft));}}strength.input(e);if(e.target.id==='library-search')$('#library-results').innerHTML=libraryCards(e.target.value);if(e.target.name==='value'&&$('#progress-value')){const h=state.habits.find(h=>h.id===$('[name=id]').value);$('#progress-value').textContent=`${e.target.value} / ${h.target} ${h.unit}`;}});
document.addEventListener('change',async e=>{if(e.target.type==='file'){const input=e.target,f=input.closest('form');if(!f)return;const file=input.files?.[0],error=f.querySelector('.form-error');error.textContent='';delete f.dataset.uploadedPhoto;try{await formPhoto(f);}catch(err){if(f.isConnected&&input.files?.[0]===file){error.textContent=err.message;input.value='';photoPreparations.delete(f);}}}});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal(true,true);if(e.key==='Tab'){const focusable=[...$('.modal').querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),select,textarea,a[href]')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('.form'))return;const formId=f.getAttribute('id')||'';e.preventDefault();if(f.dataset.submitting)return;f.dataset.submitting='true';const submit=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');submit.disabled=true;error.textContent='';const fd=new FormData(f),v=Object.fromEntries(fd),nonempty=k=>v[k]?.trim();try{const input=f.querySelector('input[type=file]');if(input)input.disabled=true;const pendingPhoto=await formPhoto(f);if(formId.startsWith('hub-')){await strength.submit(formId,v);return;}if(formId.startsWith('fitness-')){await fitness.submit(formId,v);return;}if(formId==='friend-form'){await friends.submit(v);closeModal();return;}switch(formId){
 case 'habit-form':{v.id||=(f.dataset.entityId||=D.uid());const isNew=!state.habits.some(h=>h.id===v.id);const days=fd.getAll('days').map(Number);if(!days.length)throw Error('Välj minst en dag.');if(!nonempty('name')||!nonempty('unit'))throw Error('Skriv ett namn och en enhet.');await commit(s=>{const h={id:v.id||D.uid(),name:nonempty('name'),category:v.category,target:Number(v.target),unit:nonempty('unit'),durationMinutes:Number(v.durationMinutes),cue:nonempty('cue'),days,start:today()>s.expedition.start?today():s.expedition.start,xp:15,archived:false};if(!isNew){const existing=s.habits.find(h=>h.id===v.id);if(today()<existing.start){Object.assign(existing,{...h,start:existing.start,templateId:existing.templateId});}else{existing.pending={...h,start:existing.start,xp:existing.xp,templateId:existing.templateId};existing.pendingDate=D.shiftDate(today(),1);existing.name=h.name;existing.cue=h.cue;}}else D.addHabit(s,h,today());},'Vanan är sparad.');break;}
 case 'progress-form':await complete(v.id,Number(v.value));break;
 case 'goal-form':v.id||=(f.dataset.entityId||=D.uid());if(!nonempty('name')||!nonempty('unit'))throw Error('Fyll i mål och enhet.');await commit(s=>{const g={id:v.id||D.uid(),name:nonempty('name'),category:v.category,target:Number(v.target),current:Number(v.current),unit:nonempty('unit'),deadline:v.deadline};s.goals=s.goals.filter(x=>x.id!==g.id);s.goals.push(g);},'Ditt mål har uppdaterats.');break;
 case 'reflection-form':v.id||=(f.dataset.entityId||=D.uid());if(!nonempty('win')||!nonempty('next'))throw Error('Skriv en reflektion och ett nästa steg.');await commit(s=>{const old=s.reflections.find(r=>r.id===v.id),r={id:v.id||D.uid(),date:old?.date||today(),mood:Number(v.mood),win:nonempty('win'),next:nonempty('next')};s.reflections=s.reflections.filter(x=>x.id!==r.id);s.reflections.push(r);},'En stund av självinsikt, sparad.');break;
 case 'profile-form':{if(!nonempty('name'))throw Error('Skriv ditt namn.');const photo=pendingPhoto?(f.dataset.uploadedPhoto||=await storePhoto(pendingPhoto,'avatar')):state.profile.photo;await commit(s=>s.profile={...s.profile,name:nonempty('name'),bio:v.bio.trim(),title:v.title,weight:v.weight?Number(v.weight):null,height:v.height?Number(v.height):null,photo},'Din profil är uppdaterad.');break;}
 case 'body-form':{if(!pendingPhoto&&!v.weight&&!v.waist&&!nonempty('note'))throw Error('Lägg till en bild, ett mått eller en tanke.');if(state.body.some(x=>x.date===v.date))throw Error('Du har redan sparat ett ögonblick det datumet.');if(v.date>today())throw Error('Välj idag eller ett tidigare datum.');const photo=f.dataset.uploadedPhoto||await storePhoto(pendingPhoto,'body');if(photo)f.dataset.uploadedPhoto=photo;const id=f.dataset.entityId||=D.uid();await commit(s=>s.body.push({id,date:v.date,photo,weight:v.weight?Number(v.weight):null,waist:v.waist?Number(v.waist):null,note:v.note.trim()}),'Ditt privata ögonblick är sparat.');break;}
 case 'compare-form':{const es=[v.first,v.second].map(id=>state.body.find(x=>x.id===id));$('#comparison').innerHTML=es.map(x=>`<div><img data-photo="${esc(x.photo)}" alt="Progressbild ${x.date}"><p>${dayLabel(x.date)}</p></div>`).join('');hydrateImages();return;}
 case 'post-form':{if(!nonempty('body'))throw Error('Skriv några ord om ditt steg.');if(mode!=='demo'&&!squad)throw Error('Gå med i ett squad först.');let draft=readPostDraft();draft.id??=crypto.randomUUID();if(!draft.attempted){draft.body=nonempty('body');if(pendingPhoto&&!draft.image_path)draft.image_path=await storePhoto(pendingPhoto,'posts');}draft.attempted=true;localStorage.setItem(draftKey(),JSON.stringify(draft));if(mode!=='demo')await cloud.publish(squad,draft.body,draft.image_path,draft.id);const post={id:draft.id,user_id:selfId(),name:state.profile.name,body:draft.body,image_path:draft.image_path,created_at:new Date().toISOString(),reactions:[]};if(mode==='demo'){demoPosts().unshift(post);localStorage.setItem('arc-demo-social',JSON.stringify(demoSocial));}else acceptPost(post);localStorage.removeItem(draftKey());render();toast('Ditt steg har delats med squadet.');break;}
 case 'post-photo-form':{if(!pendingPhoto)throw Error('Välj en bild.');const post=(mode==='demo'?demoPosts():social.posts).find(p=>p.id===v.post);if(!post)throw Error('Hämta flödet igen. Inlägget saknas.');const photo=f.dataset.uploadedPhoto||await storePhoto(pendingPhoto,'posts');f.dataset.uploadedPhoto=photo;const previous=post.image_path;if(mode!=='demo')await cloud.attachPostPhoto(post.id,photo);post.image_path=photo;socialRequest++;if(mode==='demo')localStorage.setItem('arc-demo-social',JSON.stringify(demoSocial));render();toast('Bilden är sparad i squadet.');if(previous&&previous!==photo)try{await deletePhoto(previous);}catch{}break;}
 case 'onboarding-form':{if(!nonempty('name'))throw Error('Skriv ditt namn.');const hs=fd.getAll('habits').map(Number);if(!hs.length)throw Error('Välj minst en vana att börja med.');await commit(s=>{s.profile.name=nonempty('name');hs.forEach(i=>D.addHabit(s,D.makeHabit(D.library[i],today()>s.expedition.start?today():s.expedition.start),today()));s.onboarded=true;},'Din expedition har börjat. Välkommen!');break;}
 case 'create-squad-form':if(!nonempty('name'))throw Error('Ge squadet ett namn.');await cloud.createSquad(nonempty('name'));await refreshSocial();render();toast('Ditt squad är skapat. Bjud in dina vänner!');break;
 case 'join-squad-form':await cloud.joinSquad(nonempty('code'));await refreshSocial();render();toast('Välkommen till squadet!');break;
 case 'mission-form':await cloud.createMission(squad,nonempty('name'),Number(v.target),D.shiftDate(D.weekKey(today()),6));await refreshSocial();toast('Ert veckouppdrag är skapat.');break;
 }closeModal();}catch(err){const current=document.getElementById(formId);const target=current?.querySelector('.form-error')||error;if(current&&current!==f)for(const [name,value] of Object.entries(v)){const field=current.elements.namedItem(name);if(field&&typeof field.value==='string'&&field.type!=='file')field.value=value;}target.textContent=err.message||'Kunde inte spara. Försök igen.';if(/conflict|revision/i.test(err.message))target.textContent='Din resa ändrades på en annan enhet. Stäng rutan, tryck på Molnsynkat och gör om ändringen.';}finally{if(f.isConnected){submit.disabled=false;const input=f.querySelector('input[type=file]');if(input)input.disabled=false;delete f.dataset.submitting;if(formId==='post-form'&&readPostDraft().attempted)f.querySelector('[name=body]').readOnly=true;}}});

async function start(){try{const user=await cloud.initialize();if(user){mode='cloud';const remote=await cloud.load();state=remote||D.blankState();if(!remote)state.profile.name=user.user_metadata?.full_name?.split(' ')[0]||'Äventyrare';await refreshSocial();}else{if(!developmentModes){mode='guest';state=D.blankState();}else{if(mode==='cloud')mode='local';state=readLocal()||(mode==='demo'?D.seedDemo():D.blankState());}}localStorage.setItem('arc-mode',mode);applyPending();selectedDay=today();const [r,t]=location.hash.slice(1).split('/');if(nav.some(x=>x[0]===r))route=r;tab=t||'';render();if(oauthFailure){history.replaceState(null,'',location.pathname+location.hash);modal('Inloggningen kunde inte slutföras',`<p class="intro">${expiredOAuth?'Inloggningsförsöket har gått ut. Starta ett nytt försök och välj ditt konto när Google öppnas.':'Google-inloggningen avbröts. Du kan starta ett nytt försök här.'}</p>${button('Fortsätt med Google','google','btn full',!cloud.googleReady?'disabled':'')}${button('Tillbaka till appen','close','btn secondary full space')}`);}else if(!state.onboarded&&mode!=='demo'&&(developmentModes||user))onboarding();else if(developmentModes&&!user&&firstVisit)authModal();}catch(e){mode=developmentModes?'local':'guest';state=developmentModes?(readLocal()||D.blankState()):D.blankState();render();toast(developmentModes?'Molnet kunde inte nås. Din lokala expedition är tillgänglig.':'Kontot kunde inte hämtas. Dina molnframsteg är kvar. Försök igen när anslutningen fungerar.');}finishStartup();setupUpdates();}
function applyPending(){SK.ensureSkills(state);D.normalizeState(state,mode==='cloud'?cloud.user?.created_at:undefined,mode==='demo');D.applyScheduledChanges(state,today());D.normalizeHabits(state);}
window.addEventListener('hashchange',()=>{const[r,t]=location.hash.slice(1).split('/');if(nav.some(x=>x[0]===r)){if(route===r&&tab===(t||''))return;route=r;tab=t||'';render();}});
document.addEventListener('visibilitychange',async()=>{if(!document.hidden){const d=today();if(selectedDay!==d){applyPending();selectedDay=d;render();}const reg=await navigator.serviceWorker?.getRegistration();reg?.update();}});
function updateModal(reg){modal('En ny version väntar',`<p class="intro">Din expedition har fått en uppdatering. Sparade framsteg finns kvar när du öppnar den nya versionen.</p>${button(I('refresh')+' Öppna nya versionen','apply-update','btn full')}`);}
let waitingUpdate=null,pendingReload=false,lastInteraction=Date.now();
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>{lastInteraction=Date.now();},{passive:true});
function applyIdleUpdate(){if(document.hidden||busy||$('#modal-root').firstElementChild||state?.training?.active||state?.strength?.active||Date.now()-lastInteraction<4000||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName))return;if(pendingReload){pendingReload=false;location.reload();return;}if(waitingUpdate?.waiting){waitingUpdate.waiting.postMessage({type:'SKIP_WAITING'});waitingUpdate=null;}}
function queueUpdate(reg){waitingUpdate=reg;setTimeout(applyIdleUpdate,4500);}
setInterval(applyIdleUpdate,15000);
async function setupUpdates(){if(!('serviceWorker' in navigator))return;try{const reg=await navigator.serviceWorker.register('./sw.js');if(reg.waiting)queueUpdate(reg);reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)queueUpdate(reg);});});let refreshing=false;const wasControlled=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(wasControlled&&!refreshing){refreshing=true;pendingReload=true;applyIdleUpdate();}});}catch{}}
setInterval(()=>{if(state&&!document.hidden&&displayedDate!==today())render();},30000);
setInterval(()=>{if(state&&!document.hidden){fitness.tick();strength.tick();}},1000);
const startupAt=performance.now();
function finishStartup(){const splash=document.querySelector('#startup-screen');if(!splash)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{splash.classList.add('ready');setTimeout(()=>splash.remove(),reduced?0:200);},reduced?0:Math.max(0,180-(performance.now()-startupAt)));}
start();

window.addEventListener('focus',()=>{if(mode==='cloud'&&route==='squad')refreshSocial();});
setInterval(()=>{if(mode==='cloud'&&route==='squad'&&document.visibilityState==='visible')refreshSocial();},30000);


